with open('/dev/vda', 'rb') as f:
    pos = 0
    chunk_size = 1024 * 1024
    while True:
        data = f.read(chunk_size)
        if not data:
            break
        if b'elderberry' in data:
            print(f"Found elderberry around offset {pos}")
            # check offset of 'elderberry' in data
            idx = 0
            while True:
                idx = data.find(b'elderberry', idx)
                if idx == -1:
                    break
                abs_pos = pos + idx
                print(f"  Exact offset: {abs_pos} (0x{abs_pos:x})")
                idx += len(b'elderberry')
        pos += len(data)
EOF
python3 /tmp/find_wal.py
